#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;
    while (T--) {
        int n;
        cin >> n;
        vector<long long> arr(n);
        for (int i = 0; i < n; ++i) {
            cin >> arr[i];
        }

        vector<long long> tail;
        tail.reserve(n);
        for (long long x : arr) {
            // upper_bound 返回第一个大于 x 的位置（对应 bisect_right）
            auto pos = upper_bound(tail.begin(), tail.end(), x);
            if (pos == tail.end()) {
                tail.push_back(x);
            } else {
                *pos = x;
            }
        }

        int L = (int)tail.size();           // 最长非递降子序列长度
        int ans = (n - L + 1) / 2;          // 最少合并次数
        cout << ans << "\n";
    }

    return 0;
}
